# tests/test_summarize.py
import math
import pandas as pd
import pytest

from csv_summary import summarize


def test_empty_dataframe():
    """When the DataFrame has no rows, the summary list should be empty."""
    df = pd.DataFrame()
    assert summarize(df) == []


@pytest.mark.parametrize(
    "df,expected",
    [
        # 1. All‑null column
        (
            pd.DataFrame({"a": [None, None, None]}),
            [
                {
                    "name": "a",
                    "dtype": pd.Series([None, None, None]).dtype,  # float64
                    "nulls": 3,
                    "mean": None,
                    "std": None,
                }
            ],
        ),
        # 2. Mixed numeric and string columns
        (
            pd.DataFrame(
                {
                    "num": [1, 2, 3, None],
                    "txt": ["x", None, "z", "y"],
                }
            ),
            [
                {
                    "name": "num",
                    "dtype": pd.Series([1, 2, 3, None]).dtype,  # float64
                    "nulls": 1,
                    "mean": 2.0,
                    "std": 1.0,
                },
                {
                    "name": "txt",
                    "dtype": pd.Series(["x", None, "z", "y"]).dtype,  # object
                    "nulls": 1,
                    "mean": None,
                    "std": None,
                },
            ],
        ),
        # 3. Column with no nulls
        (
            pd.DataFrame({"id": [10, 20, 30, 40]}),
            [
                {
                    "name": "id",
                    "dtype": pd.Series([10, 20, 30, 40]).dtype,  # int64
                    "nulls": 0,
                    "mean": 25.0,
                    "std": math.sqrt((500 / 3)),  # ≈ 12.909944487358056
                }
            ],
        ),
    ],
    ids=["all_null", "mixed", "no_null"],
)
def test_summarize_cases(df, expected):
    """Check that summarize() returns the expected list of dicts."""
    result = summarize(df)

    # The order of columns must match the DataFrame order
    assert len(result) == len(expected)
    for res, exp in zip(result, expected):
        assert res["name"] == exp["name"]
        assert res["dtype"] == exp["dtype"]
        assert res["nulls"] == exp["nulls"]
        # For floating point values we use almost‑equal comparison
        if exp["mean"] is None:
            assert res["mean"] is None
        else:
            assert math.isclose(res["mean"], exp["mean"], rel_tol=1e-9)
        if exp["std"] is None:
            assert res["std"] is None
        else:
            assert math.isclose(res["std"], exp["std"], rel_tol=1e-9)
